QUIZ_DATABASE["N5"]["dochieu"] = {"label": "Đọc Hiểu", "unitLabel": "bài", "slots": 25, "tests": {"1": {"title": "Bài 1 — Đọc hiểu Minna no Nihongo", "passage": "わたしは グエン・ヴァン・アンです。ベトナムから きました。２４さいです。ABCびょういんの いしゃです。どうぞ よろしく おねがいします。", "questions": [{"q": "Người viết tên là gì?", "options": ["グエン・ヴァン・ビン", "グエン・ティ・ホア", "グエン・ヴァン・クオン", "グエン・ヴァン・アン"], "answer": 3, "explain": "Đoạn văn mở đầu: 「わたしは グエン・ヴァン・アンです」 = Tôi là Nguyễn Văn An."}, {"q": "Người viết đến từ đâu?", "options": ["フィリピン", "ベトナム", "タイ", "インドネシア"], "answer": 1, "explain": "「ベトナムから きました」 = đến từ Việt Nam."}, {"q": "Người viết bao nhiêu tuổi?", "options": ["２４さい", "２５さい", "２０さい", "３４さい"], "answer": 0, "explain": "「２４さいです」 = 24 tuổi."}, {"q": "Người viết làm nghề gì?", "options": ["いしゃ (bác sĩ)", "がくせい (học sinh)", "せんせい (giáo viên)", "かいしゃいん (nhân viên công ty)"], "answer": 0, "explain": "「ABCびょういんの いしゃです」 = là bác sĩ của bệnh viện ABC."}]}, "2": {"title": "Bài 2 — Đọc hiểu Minna no Nihongo", "passage": "これは わたしの へやです。これは ベッドです。それは つくえです。あれは テレビです。この ほんは わたしの ほんです。その かばんは たなかさんの かばんです。", "questions": [{"q": "「これ」 trong đoạn chỉ vật nào đầu tiên?", "options": ["テレビ (tivi)", "つくえ (bàn)", "へや (phòng)", "ベッド (giường)"], "answer": 2, "explain": "Câu đầu: 「これは わたしの へやです」 — giới thiệu căn phòng."}, {"q": "Vật ở xa người nói (dùng あれ) là gì?", "options": ["ベッド", "ほん", "つくえ", "テレビ"], "answer": 3, "explain": "「あれは テレビです」 = Cái kia (xa) là tivi."}, {"q": "Quyển sách là của ai?", "options": ["たなかさん", "Người viết", "ともだち", "せんせい"], "answer": 1, "explain": "「この ほんは わたしの ほんです」 = quyển sách này là của tôi."}, {"q": "Cái cặp là của ai?", "options": ["Người viết", "おかあさん", "たなかさん", "せんせい"], "answer": 0, "explain": "「その かばんは たなかさんの かばんです」 = chiếc cặp đó là của anh Tanaka."}]}, "3": {"title": "Bài 3 — Đọc hiểu Minna no Nihongo", "passage": "ここは さくらホテルです。１かいは フロントです。２かいは レストランです。３かいは かいぎしつです。トイレは １かいに あります。", "questions": [{"q": "Khách sạn tên là gì?", "options": ["さくらホテル", "ふじホテル", "うみホテル", "やまホテル"], "answer": 0, "explain": "「ここは さくらホテルです」 = Đây là khách sạn Sakura."}, {"q": "レストラン ở tầng mấy?", "options": ["２かい", "４かい", "３かい", "１かい"], "answer": 0, "explain": "「２かいは レストランです」 = tầng 2 là nhà hàng."}, {"q": "Phòng họp （かいぎしつ) ở đâu?", "options": ["２かい", "１かい", "３かい", "５かい"], "answer": 2, "explain": "「３かいは かいぎしつです」 = tầng 3 là phòng họp."}, {"q": "トイレ ở tầng mấy?", "options": ["ちか１かい", "１かい", "３かい", "２かい"], "answer": 1, "explain": "「トイレは １かいに あります」 = nhà vệ sinh ở tầng 1."}]}, "4": {"title": "Bài 4 — Đọc hiểu Minna no Nihongo", "passage": "わたしは まいあさ ６じはんに おきます。７じに あさごはんを たべます。８じから １２じまで にほんごを べんきょうします。ごごは １じから ５じまで はたらきます。よる １１じに ねます。", "questions": [{"q": "Người viết thức dậy lúc mấy giờ?", "options": ["７じ (7 giờ)", "６じはん (6 giờ rưỡi)", "６じ (6 giờ)", "５じはん (5 giờ rưỡi)"], "answer": 1, "explain": "「６じはんに おきます」 = thức dậy lúc 6 giờ rưỡi."}, {"q": "Buổi sáng người viết học tiếng Nhật đến mấy giờ?", "options": ["１１じ", "１２じ", "１じ", "５じ"], "answer": 1, "explain": "「８じから １２じまで にほんごを べんきょうします」 = học đến 12 giờ."}, {"q": "Buổi chiều người viết làm việc từ mấy giờ đến mấy giờ?", "options": ["２じから ５じまで", "１２じから ５じまで", "１じから ６じまで", "１じから ５じまで"], "answer": 3, "explain": "「ごごは １じから ５じまで はたらきます」."}, {"q": "Tối người viết đi ngủ lúc mấy giờ?", "options": ["１１じ", "１２じ", "９じはん", "１０じ"], "answer": 0, "explain": "「よる １１じに ねます」 = ngủ lúc 11 giờ đêm."}]}, "5": {"title": "Bài 5 — Đọc hiểu Minna no Nihongo", "passage": "きのう、わたしは ともだちと きょうとへ いきました。でんしゃで いきました。きょうとは さむかったです。でも、とても たのしかったです。５じに うちへ かえりました。", "questions": [{"q": "Người viết đi Kyoto với ai?", "options": ["せんせい (thầy/cô)", "ひとり (một mình)", "かぞく (gia đình)", "ともだち (bạn)"], "answer": 3, "explain": "「ともだちと きょうとへ いきました」 = đi Kyoto cùng bạn."}, {"q": "Người viết đi bằng phương tiện gì?", "options": ["バス (xe buýt)", "タクシー (taxi)", "じてんしゃ (xe đạp)", "でんしゃ (tàu điện)"], "answer": 3, "explain": "「でんしゃで いきました」 = đi bằng tàu điện."}, {"q": "Thời tiết Kyoto thế nào?", "options": ["あめだった (mưa)", "ゆきだった (tuyết)", "あつかった (nóng)", "さむかった (lạnh)"], "answer": 3, "explain": "「きょうとは さむかったです」 = Kyoto lạnh."}, {"q": "Mấy giờ người viết về nhà?", "options": ["７じ", "５じ", "６じ", "４じ"], "answer": 1, "explain": "「５じに うちへ かえりました」 = về nhà lúc 5 giờ."}]}, "6": {"title": "Bài 6 — Đọc hiểu Minna no Nihongo", "passage": "まいばん、わたしは ほんを よみます。ときどき ともだちと こうえんで さんぽを します。しゅうまつは デパートへ いきます。デパートで かいものを します。", "questions": [{"q": "Mỗi tối người viết làm gì?", "options": ["おんがくを きく (nghe nhạc)", "テレビを みる (xem tivi)", "えいがを みる (xem phim)", "ほんを よむ (đọc sách)"], "answer": 3, "explain": "「まいばん、ほんを よみます」 = mỗi tối đọc sách."}, {"q": "Người viết đi dạo ở đâu?", "options": ["こうえん (công viên)", "がっこう (trường)", "うみ (biển)", "やま (núi)"], "answer": 0, "explain": "「こうえんで さんぽを します」 = đi dạo ở công viên."}, {"q": "Cuối tuần người viết đi đâu?", "options": ["びょういん", "えき", "デパート", "としょかん"], "answer": 2, "explain": "「しゅうまつは デパートへ いきます」 = cuối tuần đi trung tâm thương mại."}, {"q": "Ở デパート， người viết làm gì?", "options": ["べんきょう (học)", "うんどう (tập thể thao)", "しごと (làm việc)", "かいもの (mua sắm)"], "answer": 3, "explain": "「デパートで かいものを します」 = mua sắm ở trung tâm thương mại."}]}, "7": {"title": "Bài 7 — Đọc hiểu Minna no Nihongo", "passage": "きのうは たんじょうびでした。ともだちに はなを もらいました。せんせいに プレゼントを あげました。もう クリスマスの プレゼントを かいました。", "questions": [{"q": "Hôm qua là ngày gì của người viết?", "options": ["たんじょうび (sinh nhật)", "おしょうがつ (Tết)", "けっこんしき (đám cưới)", "クリスマス"], "answer": 0, "explain": "「きのうは たんじょうびでした」 = hôm qua là sinh nhật."}, {"q": "Người viết nhận hoa từ ai?", "options": ["おとうさん", "せんせい", "おかあさん", "ともだち"], "answer": 3, "explain": "「ともだちに はなを もらいました」 = nhận hoa từ bạn."}, {"q": "Người viết tặng quà cho ai?", "options": ["おねえさん", "かぞく", "せんせい", "ともだち"], "answer": 2, "explain": "「せんせいに プレゼントを あげました」 = tặng quà cho thầy/cô."}, {"q": "Người viết đã mua quà Giáng sinh chưa?", "options": ["まだ かいていません", "かいません", "これから かいます", "もう かいました (đã mua rồi)"], "answer": 3, "explain": "「もう クリスマスの プレゼントを かいました」 = đã mua rồi."}]}, "8": {"title": "Bài 8 — Đọc hiểu Minna no Nihongo", "passage": "わたしの まちは しずかで、きれいです。でも、こうつうは あまり べんりじゃありません。レストランは とても おいしいです。ひとびとは しんせつです。", "questions": [{"q": "Quê/thị trấn của người viết thế nào?", "options": ["あつくて うるさい", "にぎやかで きたない", "さむくて くらい", "しずかで きれい"], "answer": 3, "explain": "「まちは しずかで、きれいです」 = thị trấn yên tĩnh và sạch đẹp."}, {"q": "Giao thông （こうつう) thế nào?", "options": ["あまり べんりじゃない", "すこし べんり", "ぜんぜん もんだいない", "とても べんり"], "answer": 0, "explain": "「こうつうは あまり べんりじゃありません」 = giao thông không tiện lắm (あまり + phủ định)."}, {"q": "Đồ ăn ở nhà hàng thế nào?", "options": ["あまり おいしくない", "とても おいしい", "たかすぎる", "からすぎる"], "answer": 1, "explain": "「レストランは とても おいしいです」 = nhà hàng rất ngon."}, {"q": "Con người ở đó thế nào?", "options": ["つめたい (lạnh lùng)", "こわい (đáng sợ)", "うるさい (ồn ào)", "しんせつ (tốt bụng)"], "answer": 3, "explain": "「ひとびとは しんせつです」 = mọi người tốt bụng."}]}, "9": {"title": "Bài 9 — Đọc hiểu Minna no Nihongo", "passage": "わたしは スポーツが すきです。とくに サッカーが すきです。テニスは あまり すきじゃありません。にほんごが すこし わかります。えいごは ぜんぜん わかりません。", "questions": [{"q": "Người viết đặc biệt thích môn nào?", "options": ["すいえい (bơi lội)", "テニス (quần vợt)", "やきゅう (bóng chày)", "サッカー (bóng đá)"], "answer": 3, "explain": "「とくに サッカーが すきです」 = đặc biệt thích bóng đá."}, {"q": "Môn nào người viết không thích lắm?", "options": ["バスケットボール", "ゴルフ", "サッカー", "テニス"], "answer": 3, "explain": "「テニスは あまり すきじゃありません」 = không thích tennis lắm."}, {"q": "Người viết hiểu tiếng Nhật ở mức nào?", "options": ["よく (rất rõ)", "だいたい (hầu hết)", "すこし (một chút)", "ぜんぜん (hoàn toàn không)"], "answer": 2, "explain": "「にほんごが すこし わかります」 = hiểu tiếng Nhật một chút."}, {"q": "Tiếng Anh của người viết thế nào?", "options": ["ペラペラ", "ぜんぜん わからない", "よく わかる", "すこし わかる"], "answer": 1, "explain": "「えいごは ぜんぜん わかりません」 = hoàn toàn không hiểu tiếng Anh."}]}, "10": {"title": "Bài 10 — Đọc hiểu Minna no Nihongo", "passage": "わたしの へやは ひろいです。つくえの うえに パソコンが あります。つくえの したに かばんが あります。まどの ちかくに ベッドが あります。へやの なかに テレビも あります。", "questions": [{"q": "Trên bàn có gì?", "options": ["ほん", "かばん", "テレビ", "パソコン"], "answer": 3, "explain": "「つくえの うえに パソコンが あります」 = trên bàn có máy tính."}, {"q": "Cái cặp ở đâu?", "options": ["ベッドの うえ", "つくえの うえ", "つくえの した", "まどの ちかく"], "answer": 2, "explain": "「つくえの したに かばんが あります」 = dưới bàn có cái cặp."}, {"q": "Giường ở đâu?", "options": ["へやの そと", "ドアの まえ", "まどの ちかく", "つくえの した"], "answer": 2, "explain": "「まどの ちかくに ベッドが あります」 = giường ở gần cửa sổ."}, {"q": "Phòng của người viết thế nào?", "options": ["くらい (tối)", "きたない (bẩn)", "せまい (chật)", "ひろい (rộng)"], "answer": 3, "explain": "「わたしの へやは ひろいです」 = phòng rộng."}]}, "11": {"title": "Bài 11 — Đọc hiểu Minna no Nihongo", "passage": "きょうは かぞくと こうえんへ いきました。こうえんには ひとが たくさん いました。わたしたちは りんごを ５つ かいました。１じかん さんぽを しました。", "questions": [{"q": "Người viết đi công viên với ai?", "options": ["せんせい", "ひとり", "ともだち", "かぞく"], "answer": 3, "explain": "「かぞくと こうえんへ いきました」 = đi cùng gia đình."}, {"q": "Công viên có đông người không?", "options": ["２にん いた", "すこし いた", "たくさん いた", "だれも いなかった"], "answer": 2, "explain": "「ひとが たくさん いました」 = có rất nhiều người."}, {"q": "Họ mua bao nhiêu táo?", "options": ["４つ", "３つ", "６つ", "５つ"], "answer": 3, "explain": "「りんごを ５つ かいました」 = mua 5 quả táo."}, {"q": "Họ đi dạo trong bao lâu?", "options": ["２じかん", "１じかんはん", "３０ぷん", "１じかん"], "answer": 3, "explain": "「１じかん さんぽを しました」 = đi dạo 1 tiếng."}]}, "12": {"title": "Bài 12 — Đọc hiểu Minna no Nihongo", "passage": "きのうは あめでした。きょうは きのうより あたたかいです。あしたは もっと あたたかく なります。この １かげつで きょうが いちばん あたたかいです。", "questions": [{"q": "Thời tiết hôm qua thế nào?", "options": ["くもり (nhiều mây)", "はれ (nắng)", "あめ (mưa)", "ゆき (tuyết)"], "answer": 2, "explain": "「きのうは あめでした」 = hôm qua mưa."}, {"q": "Hôm nay so với hôm qua thế nào?", "options": ["あめが おおい hơn", "あたたかい hơn", "おなじ", "さむい hơn"], "answer": 1, "explain": "「きょうは きのうより あたたかいです」 = hôm nay ấm hơn hôm qua (so sánh より)."}, {"q": "Ngày mai sẽ thế nào?", "options": ["さむく なる", "あめに なる", "かぜが つよく なる", "もっと あたたかく なる"], "answer": 3, "explain": "「あしたは もっと あたたかく なります」 = mai còn ấm hơn nữa."}, {"q": "Ngày ấm nhất trong tháng này là ngày nào?", "options": ["せんしゅうの どようび", "きのう (hôm qua)", "きょう (hôm nay)", "あした (ngày mai)"], "answer": 2, "explain": "「この １かげつで きょうが いちばん あたたかいです」 = hôm nay ấm nhất tháng."}]}, "13": {"title": "Bài 13 — Đọc hiểu Minna no Nihongo", "passage": "わたしは あたらしい じてんしゃが ほしいです。らいしゅう デパートへ じてんしゃを かいに いきます。おかねは すこししか ありません。ですから、やすい じてんしゃを さがします。", "questions": [{"q": "Người viết muốn có gì?", "options": ["あたらしい とけい", "あたらしい くるま", "あたらしい パソコン", "あたらしい じてんしゃ"], "answer": 3, "explain": "「あたらしい じてんしゃが ほしいです」 = muốn có xe đạp mới."}, {"q": "Tuần sau người viết đi đâu?", "options": ["デパート", "としょかん", "うみ", "じてんしゃや"], "answer": 0, "explain": "「らいしゅう デパートへ ... いきます」 = tuần sau đi trung tâm thương mại."}, {"q": "Người viết sẽ mua xe đạp loại nào?", "options": ["おおきい じてんしゃ", "やすい じてんしゃ", "あかい じてんしゃ", "たかい じてんしゃ"], "answer": 1, "explain": "Vì ít tiền nên 「やすい じてんしゃを さがします」 = tìm xe đạp rẻ."}, {"q": "Vì sao người viết tìm xe rẻ?", "options": ["おかねが すこししか ないから", "デパートが とおいから", "じかんが ないから", "じてんしゃが すきだから"], "answer": 0, "explain": "「おかねは すこししか ありません。ですから...」 = tiền chỉ có ít, vì vậy tìm xe rẻ."}]}, "14": {"title": "Bài 14 — Đọc hiểu Minna no Nihongo", "passage": "すみません、ちょっと まって ください。いま コピーを して います。コピーが おわってから、しりょうを わたします。この しりょうは あしたの かいぎで つかいます。", "questions": [{"q": "Người viết đang làm gì?", "options": ["でんわを かけて いる", "コピーを して いる", "かいぎを して いる", "しりょうを よんで いる"], "answer": 1, "explain": "「いま コピーを して います」 = đang photocopy."}, {"q": "Khi nào người viết đưa tài liệu?", "options": ["かいぎの あと", "コピーが おわってから", "あした", "いま すぐ"], "answer": 1, "explain": "「コピーが おわってから、しりょうを わたします」 = photocopy xong mới đưa."}, {"q": "Tài liệu dùng cho việc gì?", "options": ["あしたの かいぎ", "らいしゅうの りょこう", "きょうの テスト", "しゅくだい"], "answer": 0, "explain": "「あしたの かいぎで つかいます」 = dùng cho cuộc họp ngày mai."}, {"q": "Người nghe được nhờ làm gì?", "options": ["かいぎに いく", "しりょうを よむ", "ちょっと まつ", "コピーを する"], "answer": 2, "explain": "「ちょっと まって ください」 = xin chờ một chút."}]}, "15": {"title": "Bài 15 — Đọc hiểu Minna no Nihongo", "passage": "ここは としょかんです。としょかんでは おおきな こえで はなしては いけません。でも、ほんを かりても いいです。としょかんの ひとは しずかに ほんを よんで います。", "questions": [{"q": "Đoạn văn nói về nơi nào?", "options": ["がっこう (trường)", "こうえん (công viên)", "としょかん (thư viện)", "びょういん (bệnh viện)"], "answer": 2, "explain": "「ここは としょかんです」 = Đây là thư viện."}, {"q": "Việc gì bị cấm ở thư viện?", "options": ["おおきな こえで はなす", "すわって よむ", "ほんを かりる", "しずかに よむ"], "answer": 0, "explain": "「おおきな こえで はなしては いけません」 = không được nói to."}, {"q": "Việc gì được phép làm?", "options": ["ほんを かりる", "でんわを かける", "たばこを すう", "しゃしんを とる"], "answer": 0, "explain": "「ほんを かりても いいです」 = được mượn sách."}, {"q": "Mọi người trong thư viện đang làm gì?", "options": ["たべて いる", "おおきな こえで はなして いる", "しずかに ほんを よんで いる", "ねて いる"], "answer": 2, "explain": "「しずかに ほんを よんで います」 = đang yên lặng đọc sách."}]}, "16": {"title": "Bài 16 — Đọc hiểu Minna no Nihongo", "passage": "まいあさ、わたしは ６じに おきます。かおを あらって、あさごはんを たべて、がっこうへ いきます。がっこうは じてんしゃで １５ふんです。かえってから、しゅくだいを します。", "questions": [{"q": "Người viết dậy lúc mấy giờ?", "options": ["５じ", "６じはん", "７じ", "６じ"], "answer": 3, "explain": "「６じに おきます」 = dậy lúc 6 giờ."}, {"q": "Sau khi rửa mặt, người viết làm gì?", "options": ["しゅくだいを する", "あさごはんを たべる", "シャワーを あびる", "がっこうへ いく"], "answer": 1, "explain": "Thứ tự thể て: 「かおを あらって、あさごはんを たべて」 = rửa mặt rồi ăn sáng."}, {"q": "Đến trường bằng xe đạp mất bao lâu?", "options": ["１じかん", "１５ふん", "３０ぷん", "５ふん"], "answer": 1, "explain": "「じてんしゃで １５ふんです」 = 15 phút bằng xe đạp."}, {"q": "Về nhà rồi người viết làm gì?", "options": ["テレビを みる", "しゅくだい", "さんぽ", "りょうり"], "answer": 1, "explain": "「かえってから、しゅくだいを します」 = về nhà rồi làm bài tập."}]}, "17": {"title": "Bài 17 — Đọc hiểu Minna no Nihongo", "passage": "あしたは スポーツの ひです。８じまでに がっこうへ こなければ なりません。くつを わすれないで ください。みずを もって きても いいです。", "questions": [{"q": "Ngày mai học sinh phải đến trường trước mấy giờ?", "options": ["９じ", "８じはん", "７じ", "８じ"], "answer": 3, "explain": "「８じまでに がっこうへ こなければ なりません」 = phải đến trước 8 giờ."}, {"q": "Học sinh không được quên gì?", "options": ["くつ (giày)", "ほん (sách)", "かさ (ô)", "ぼうし (mũ)"], "answer": 0, "explain": "「くつを わすれないで ください」 = đừng quên giày."}, {"q": "Học sinh có được mang nước không?", "options": ["もって きても いい", "もって きては いけない", "もって こなければ ならない", "もって こない"], "answer": 0, "explain": "「みずを もって きても いいです」 = được mang nước theo."}, {"q": "Ngày mai là ngày gì?", "options": ["りょこうの ひ", "やすみの ひ", "テストの ひ", "スポーツの ひ"], "answer": 3, "explain": "「あしたは スポーツの ひです」 = mai là ngày thể thao."}]}, "18": {"title": "Bài 18 — Đọc hiểu Minna no Nihongo", "passage": "わたしの しゅみは りょうりです。すしを つくることが できます。でも、ケーキを つくることは できません。ねる まえに、ほんを よみます。", "questions": [{"q": "Sở thích của người viết là gì?", "options": ["えいが (phim)", "うんどう (thể thao)", "りょうり (nấu ăn)", "おんがく (âm nhạc)"], "answer": 2, "explain": "「しゅみは りょうりです」 = sở thích là nấu ăn."}, {"q": "Người viết làm được món gì?", "options": ["カレー", "ピザ", "すし", "ケーキ"], "answer": 2, "explain": "「すしを つくることが できます」 = làm được sushi."}, {"q": "Món nào người viết không làm được?", "options": ["すし", "サラダ", "ケーキ", "スープ"], "answer": 2, "explain": "「ケーキを つくることは できません」 = không làm được bánh kem."}, {"q": "Trước khi ngủ người viết làm gì?", "options": ["おんがくを きく", "テレビを みる", "ほんを よむ", "りょうりを する"], "answer": 2, "explain": "「ねる まえに、ほんを よみます」 = trước khi ngủ thì đọc sách."}]}, "19": {"title": "Bài 19 — Đọc hiểu Minna no Nihongo", "passage": "わたしは うみに およいだことが あります。でも、ふじさんに のぼったことは ありません。ことしの なつ、ふじさんに のぼりたいです。からだが つよく なりました。", "questions": [{"q": "Người viết đã từng làm gì?", "options": ["さしみを たべる", "スキーを する", "ふじさんに のぼる", "うみに およぐ"], "answer": 3, "explain": "「うみに およいだことが あります」 = đã từng bơi ở biển."}, {"q": "Việc gì người viết chưa từng làm?", "options": ["ほんを よむ", "うみに およぐ", "りょうりを つくる", "ふじさんに のぼる"], "answer": 3, "explain": "「ふじさんに のぼったことは ありません」 = chưa từng leo núi Phú Sĩ."}, {"q": "Mùa hè năm nay người viết muốn làm gì?", "options": ["くにへ かえる", "にほんごを べんきょうする", "うみへ いく", "ふじさんに のぼる"], "answer": 3, "explain": "「ことしの なつ、ふじさんに のぼりたいです」 = hè này muốn leo núi Phú Sĩ."}, {"q": " cơ thể người viết thế nào?", "options": ["つよく なった", "よわく なった", "かわらない", "おおきく なった"], "answer": 0, "explain": "「からだが つよく なりました」 = cơ thể đã khỏe lên."}]}, "20": {"title": "Bài 20 — Đọc hiểu Minna no Nihongo", "passage": "「あした えいが、みる？」「うん、みる。なんじから？」「３じから。えきで あおう。」「わかった。じゃ、あした。」", "questions": [{"q": "Hai người hẹn nhau làm gì ngày mai?", "options": ["かいものを する", "えいがを みる", "さんぽを する", "りょうりを つくる"], "answer": 1, "explain": "Hội thoại thân mật Bài 20: 「えいが、みる？」 = Mai xem phim không?"}, {"q": "Phim bắt đầu lúc mấy giờ?", "options": ["２じ", "３じ", "４じ", "５じ"], "answer": 1, "explain": "「３じから」 = từ 3 giờ."}, {"q": "Họ hẹn gặp nhau ở đâu?", "options": ["カフェ", "えき (ga)", "こうえん", "がっこう"], "answer": 1, "explain": "「えきで あおう」 = gặp nhau ở ga nhé."}, {"q": "Văn phong của đoạn hội thoại là gì?", "options": ["Văn viết báo cáo", "Thể thường, thân mật", "Thư thương mại", "Kính ngữ trang trọng"], "answer": 1, "explain": "Câu như 「みる？」「わかった」 là thể thường dùng với bạn bè — nội dung chính Bài 20."}]}, "21": {"title": "Bài 21 — Đọc hiểu Minna no Nihongo", "passage": "あしたは あめが ふると おもいます。せんせいは「あした テストが あります」と いいました。ですから、きょうの よる べんきょうします。テストは むずかしいでしょう。", "questions": [{"q": "Người viết nghĩ ngày mai thế nào?", "options": ["はれる", "ゆきが ふる", "あめが ふる", "かぜが つよい"], "answer": 2, "explain": "「あめが ふると おもいます」 = nghĩ mai sẽ mưa."}, {"q": "Thầy/cô đã nói gì?", "options": ["あした りょこうに いく", "あしたは やすみ", "あした テストが ある", "あしたは テストが ない"], "answer": 2, "explain": "Trích dẫn: 「あした テストが あります」と いいました."}, {"q": "Tối nay người viết làm gì?", "options": ["ともだちと あそぶ", "べんきょうする", "はやく ねる", "えいがを みる"], "answer": 1, "explain": "「ですから、きょうの よる べんきょうします」 = vì vậy tối nay học bài."}, {"q": "Người viết dự đoán bài kiểm tra thế nào?", "options": ["むずかしいでしょう", "たのしいでしょう", "かんたんでしょう", "みじかいでしょう"], "answer": 0, "explain": "「テストは むずかしいでしょう」 = chắc bài kiểm tra sẽ khó."}]}, "22": {"title": "Bài 22 — Đọc hiểu Minna no Nihongo", "passage": "あそこで はなして いる ひとは、わたしの せんせいです。せんせいは まいにち おしえる ことが できる ひとが すくない じゅぎょうを しています。きのう よんだ ほんは せんせいの ほんです。", "questions": [{"q": "Người đang nói chuyện ở đằng kia là ai?", "options": ["かいしゃいん", "ともだち", "おかあさん", "せんせい"], "answer": 3, "explain": "「あそこで はなして いる ひとは、わたしの せんせいです」 — mệnh đề quan hệ Bài 22."}, {"q": "Quyển sách người viết đọc hôm qua là của ai?", "options": ["としょかん", "じぶん", "ともだち", "せんせい"], "answer": 3, "explain": "「きのう よんだ ほんは せんせいの ほんです」 = sách của thầy/cô."}, {"q": "Đoạn văn dùng mẫu ngữ pháp chính nào?", "options": ["Thể たら", "Thể て いけません", "Thể khả năng", "Thể thường bổ nghĩa cho danh từ"], "answer": 3, "explain": "Các cụm 「はなして いる ひと」「よんだ ほん」 là mệnh đề quan hệ — trọng tâm Bài 22."}, {"q": "Câu nào đúng với đoạn văn?", "options": ["Thầy đang ngủ ở nhà", "Người viết chưa đọc sách", "Cuốn sách là của bạn", "Thầy đang nói chuyện ở đằng kia"], "answer": 3, "explain": "Câu đầu đoạn văn nói rõ thầy đang nói chuyện ở đằng kia."}]}, "23": {"title": "Bài 23 — Đọc hiểu Minna no Nihongo", "passage": "この ボタンを おすと、ドアが あきます。えきに ついたとき、ともだちに でんわを かけます。まっすぐ いくと、ひだりに コンビニが あります。", "questions": [{"q": "Điều gì xảy ra khi bấm nút?", "options": ["ドアが しまる", "でんきが つく", "おとが なる", "ドアが あく"], "answer": 3, "explain": "「ボタンを おすと、ドアが あきます」 = bấm nút thì cửa mở (～と Bài 23)."}, {"q": "Khi đến ga, người viết làm gì?", "options": ["ほんを よむ", "ともだちに でんわを かける", "ごはんを たべる", "うちへ かえる"], "answer": 1, "explain": "「えきに ついたとき、ともだちに でんわを かけます」."}, {"q": "Đi thẳng thì thấy gì ở bên trái?", "options": ["びょういん", "えき", "がっこう", "コンビニ"], "answer": 3, "explain": "「まっすぐ いくと、ひだりに コンビニが あります」 = đi thẳng thì bên trái có cửa hàng tiện lợi."}, {"q": "Mẫu ～と trong đoạn có nghĩa là gì?", "options": ["Đang làm A thì...", "Sau khi làm A", "Vì A nên B", "Cứ làm A thì tự nhiên xảy ra B"], "answer": 3, "explain": "～と Bài 23 chỉ điều kiện tất yếu/hệ quả tự nhiên và chỉ đường."}]}, "24": {"title": "Bài 24 — Đọc hiểu Minna no Nihongo", "passage": "きのう、ともだちが ケーキを つくって くれました。わたしは たなかさんに しゅくだいを おしえて もらいました。あには わたしに にもつを もって くれました。", "questions": [{"q": "Bạn đã làm gì cho người viết?", "options": ["ケーキを かって くれた", "ケーキを たべて くれた", "ケーキを うって くれた", "ケーキを つくって くれた"], "answer": 3, "explain": "「ともだちが ケーキを つくって くれました」 = bạn làm bánh cho tôi."}, {"q": "Người viết được anh Tanaka làm gì cho?", "options": ["にもつを もつ", "しゅくだいを おしえる", "ほんを かす", "ケーキを つくる"], "answer": 1, "explain": "「たなかさんに しゅくだいを おしえて もらいました」 = được Tanaka chỉ bài tập cho."}, {"q": "Anh trai đã làm gì giúp người viết?", "options": ["にもつを すてる", "にもつを あらう", "にもつを かう", "にもつを もつ"], "answer": 3, "explain": "「あには わたしに にもつを もって くれました」 = anh xách hành lý giúp tôi."}, {"q": "Các mẫu ～てくれました/～てもらいました trong đoạn diễn tả điều gì?", "options": ["Mệnh lệnh", "Ân huệ — người khác làm gì đó cho mình", "Khả năng", "Kinh nghiệm quá khứ"], "answer": 1, "explain": "Bài 24: Vて あげる/もらう/くれる diễn tả việc cho-nhận ân huệ."}]}, "25": {"title": "Bài 25 — Đọc hiểu Minna no Nihongo", "passage": "おかねが あったら、りょこうに いきたいです。でも、おかねが あっても、じかんが なければ いけません。もし １００まんえん あったら、くにへ かえって、かぞくに あいたいです。", "questions": [{"q": "Nếu có tiền, người viết muốn làm gì?", "options": ["いえを たてる", "りょこうに いく", "くるまを かう", "べんきょうする"], "answer": 1, "explain": "「おかねが あったら、りょこうに いきたいです」 — điều kiện ～たら Bài 25."}, {"q": "Chỉ có tiền thôi có đủ để đi không?", "options": ["Không — không có thời gian thì không đi được", "Không liên quan đến thời gian", "Chưa biết", "Đủ — có tiền là đi được"], "answer": 0, "explain": "「おかねが あっても、じかんが なければ いけません」 = dù có tiền, không có thời gian thì không đi được."}, {"q": "Nếu có 1 triệu yên, người viết muốn làm gì?", "options": ["がっこうを つくる", "くにへ かえって かぞくに あう", "あたらしい くるまを かう", "りょこうに いく"], "answer": 1, "explain": "「もし １００まんえん あったら、くにへ かえって、かぞくに あいたいです」."}, {"q": "Mẫu ～ても trong đoạn có nghĩa là gì?", "options": ["Vì... nên", "Sau khi...", "Khi... thì", "Dù... cũng"], "answer": 3, "explain": "～ても = dù...cũng (nhượng bộ giả định) — trọng tâm Bài 25 cùng với ～たら."}]}}};
